//! The BaseJIT stencil tables (`quench_bjit::rustc`): one per CPU variant, generated by `quench-bjit/build.rs`
//! from the compiled rows and exported by name, which `quench_bjit` declares. `quench-layers` links this crate.
use quench_bjit::rustc::{RawLibrary, RawStencil};

mod generated {
    use super::{RawLibrary, RawStencil};
    include!(concat!(env!("OUT_DIR"), "/rustc_stencils.rs"));
}

#[unsafe(no_mangle)]
static QUENCH_STENCILS_BASELINE: &RawLibrary = &generated::BASELINE;
#[unsafe(no_mangle)]
static QUENCH_STENCILS_V3: &RawLibrary = &generated::V3;
